args.content:
'use server'

import { revalidatePath } from 'next/cache'
import { getNotificationsEnabled, setNotificationsEnabled } from './preferences'

export async function toggleNotifications() {
  // Flip the stored preference.
  setNotificationsEnabled(!getNotificationsEnabled())

  // Refresh the current page so the Server Component re-renders with the
  // updated value. revalidatePath is the recommended way to refresh the
  // current route from a Server Action — unlike redirect(), it stays on
  // the same page.
  revalidatePath('/')
}

