args.content:
import { toggleNotifications } from './actions'
import { getNotificationsEnabled } from './preferences'

export default function Home() {
  const enabled = getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

